#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime, timezone
import base64
import gzip
import hashlib
import py_compile
import shutil

ROOT = Path("/home/mwynn/nfl_data_engine")
APP = ROOT / "app.py"
SHOWDOWN_SOLVER = ROOT / "fanduel_nfl_showdown_solver_v1.py"
SHOWDOWN_POOL = ROOT / "data/fanduel/single_game/derived/single_game_projection_pool.parquet"
EXPECTED_APP_SHA = "81d7eb2b1b82a3adcecdc13384e923df2c86f5fc85816fc41b185621c3437325"
EXPECTED_SHOWDOWN_SOLVER_SHA = "a08c3cad60a36185f9d56edbd31006bcb93010de498fbb21d3a4097c0e9cd14a"
EXPECTED_SHOWDOWN_POOL_SHA = "9fcc9fb66da957d419f2660ff49aaa596a1669736129f6e4c40b50e3e084e8bf"
EXPECTED_NEW_APP_SHA = "df786a50759414901c56dd1d04fd05417a5fdd3547f659f13efacf71ae5d9531"
PAYLOAD_B64 = ""


def sha256(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def fail(message):
    print(f"FAIL_CLOSED={message}")
    raise SystemExit(2)


print("=" * 118)
print("WFS NFL — SHOWDOWN UI-1B INSTALLER")
print("Exact baseline gate • backup • isolated Single-Game UI • Classic preservation • compile")
print("=" * 118)

if not APP.exists():
    fail(f"missing app.py: {APP}")
if sha256(APP) != EXPECTED_APP_SHA:
    fail(f"app.py SHA mismatch: {sha256(APP)}")
if not SHOWDOWN_SOLVER.exists() or sha256(SHOWDOWN_SOLVER) != EXPECTED_SHOWDOWN_SOLVER_SHA:
    fail("Showdown Solver V1 missing or SHA mismatch")
if not SHOWDOWN_POOL.exists() or sha256(SHOWDOWN_POOL) != EXPECTED_SHOWDOWN_POOL_SHA:
    fail("Showdown projection pool missing or SHA mismatch")

new_bytes = gzip.decompress(base64.b64decode(PAYLOAD_B64))
if hashlib.sha256(new_bytes).hexdigest() != EXPECTED_NEW_APP_SHA:
    fail("embedded app.py payload SHA mismatch")
new_text = new_bytes.decode("utf-8")

classic_required = [
    'UI_SOLVER = APP_DIR / "fanduel_nfl_ui_solver.py"',
    'SOLVER_TABLE = "fanduel_solver_ready_pool"',
    '"⚡ Generate GPP Portfolio"',
    '**FanDuel NFL Classic lineup**',
    'render_late_swap_stage1(selected_pool, selected_slate)',
]
for fragment in classic_required:
    if fragment not in new_text:
        fail(f"Classic preservation gate missing: {fragment}")

showdown_required = [
    'SHOWDOWN_SOLVER = APP_DIR / "fanduel_nfl_showdown_solver_v1.py"',
    'SHOWDOWN_POOL = APP_DIR / "data" / "fanduel" / "single_game"',
    'def render_showdown_builder(',
    '["Classic", "Single-Game"]',
    '"⚡ Generate Single-Game Lineups"',
    'if contest_format == "Single-Game":',
]
for fragment in showdown_required:
    if fragment not in new_text:
        fail(f"Showdown integration gate missing: {fragment}")

stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
backup = ROOT / f"app.py.pre-showdown-ui1b-{stamp}.bak"
shutil.copy2(APP, backup)
if sha256(backup) != EXPECTED_APP_SHA:
    fail("backup SHA mismatch")
print(f"BACKUP={backup}")
print(f"BACKUP_SHA256={sha256(backup)}")

candidate = ROOT / ".app.py.showdown-ui1b.tmp"
candidate.write_bytes(new_bytes)
try:
    py_compile.compile(str(candidate), doraise=True)
except Exception as exc:
    candidate.unlink(missing_ok=True)
    fail(f"py_compile failed: {exc}")

if sha256(candidate) != EXPECTED_NEW_APP_SHA:
    candidate.unlink(missing_ok=True)
    fail("candidate SHA mismatch after write")

candidate.replace(APP)
print(f"NEW_APP_SHA256={sha256(APP)}")
print("PY_COMPILE=PASS")
print("CLASSIC_UI_SOLVER_PATH_PRESERVED=TRUE")
print("CLASSIC_SOLVER_TABLE_PRESERVED=TRUE")
print("CLASSIC_GENERATOR_FRAGMENT_PRESERVED=TRUE")
print("CLASSIC_LATE_SWAP_FRAGMENT_PRESERVED=TRUE")
print("SHOWDOWN_UI_ISOLATED=TRUE")
print("SHOWDOWN_DYNAMIC_READY_SLATES=TRUE")
print("SHOWDOWN_PUBLIC_LINEUPS=1,5,10,20")
print("SHOWDOWN_ADMIN_DIAGNOSTICS_ONLY=TRUE")
print("SERVICE_RESTARTED=FALSE")
print("NFL_SHOWDOWN_UI_1B_STATUS=PASS")
